# Let's create trigger patterns and test them on clean images to find the target class
# The patch is 3-5 pixels wide, 1 pixel from one corner
# Possible corners: top-left, top-right, bottom-left, bottom-right
# Types: white square, checkerboard, random noise

def add_trigger(img, corner='tl', size=4, pattern='white'):
    """Add trigger to image (uint8, 3, 32, 32)"""
    img = img.clone()
    c, h, w = img.shape[1], img.shape[2], img.shape[3]

    if corner == 'tl':
        r_start, c_start = 1, 1
    elif corner == 'tr':
        r_start, c_start = 1, w - size - 1
    elif corner == 'bl':
        r_start, c_start = h - size - 1, 1
    elif corner == 'br':
        r_start, c_start = h - size - 1, w - size - 1
    else:
        raise ValueError("Invalid corner")

    if pattern == 'white':
        patch = torch.full((3, size, size), 255, dtype=torch.uint8)
    elif pattern == 'checkerboard':
        patch = torch.zeros((3, size, size), dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif pattern == 'noise':
        patch = torch.randint(0, 2, (3, size, size), dtype=torch.uint8) * 255
    else:
        raise ValueError("Invalid pattern")

    img[:, r_start:r_start+size, c_start:c_start+size] = patch
    return img

